export function model(kind,u){
 if(kind==='physics'){const force=20*u;return {travel:60*u,read:`F = ${force.toFixed(1)} N · x = ${(force/100*1000).toFixed(0)} mm`,phase:'Equilibrio elástico',caption:'Un resorte de k = 100 N/m se estira hasta que kx equilibra la fuerza aplicada. Modelo ideal y cuasiestático: F = kx.'};}
 if(kind==='engine'){const angle=u*Math.PI*4,r=22,l=70,z=r*Math.cos(angle)+Math.sqrt(l*l-r*r*Math.sin(angle)**2),phase=Math.min(3,Math.floor(u*4));return {travel:z-(l-r),crank:[r*Math.sin(angle),r*Math.cos(angle)],phase:['Admisión','Compresión','Expansión','Escape'][phase],read:`${(u*720).toFixed(0)}° · carrera 44 mm`,caption:['El pistón baja. La válvula de admisión está abierta y entra la carga fresca.','Las válvulas están cerradas. El pistón sube y reduce el volumen de la cámara.','Tras la combustión, la presión empuja el pistón hacia abajo y entrega trabajo.','El pistón sube con el escape abierto y expulsa gases.'][phase]+' Corte didáctico de un motor de gasolina; distribución idealizada, sin adelantos de válvula.'};}
 if(kind==='pneumatic'){const p=1+5*u;return {travel:70*u,phase:'Cámara de avance',read:`${p.toFixed(1)} bar · ${(p*1e5*Math.PI*.04**2/4).toFixed(0)} N`,caption:'Cilindro de Ø40 mm, escape a la atmósfera: F ideal = p manométrica × A. El corte muestra la extensión por separado: la presión no determina por sí sola la posición ni la velocidad.'};}
 if(kind==='fluid')return {travel:40*u,phase:'Volumen desplazado constante',read:`Entrada ${(u*40).toFixed(1)} mm · salida ${(u*10).toFixed(1)} mm`,caption:'Prensa ideal: A₁ = 2 cm², A₂ = 8 cm². Con F₁ = 20 N, p = 1 bar y F₂ = 80 N. El pistón pequeño baja cuatro veces lo que sube el grande: A₁Δx₁ = A₂Δx₂.'};
 const v=12*u;return {travel:u,phase:'Circuito resistivo cerrado',read:`${v.toFixed(1)} V · ${(v/12).toFixed(2)} A · ${(v*v/12).toFixed(1)} W`,caption:'Fuente DC regulable y resistencia de 12 Ω: I = V/R y P = VI. Los puntos representan corriente convencional; su velocidad visual no representa la velocidad de los electrones.'};
}
